text:
:host,
.recipient-avatar {
  box-sizing: border-box;
  display: inline-flex;
  block-size: var(--recipient-avatar-size);
  inline-size: var(--recipient-avatar-size);
  border-radius: 50%;
  margin-inline: 6px;
  text-align: center;
  overflow: hidden;
  color: var(--color-text-base);
  background-color: var(--color-surface-deep);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, currentColor 30%, transparent);
  align-items: center;
  justify-content: center;
  flex: 0 0 auto;
